use serde_json::{json, Value};

pub(super) fn storage() -> Vec<Value> {
    vec![
        json!({"type":"function","function":{"name":"storage_analyze","description":"Analyze a user-selected directory without modifying files. Returns a cancellable storage_scan task; poll task_progress for the report. Reports logical and filesystem-allocated bytes, suffix categories and largest files; NOT reclaimable space or application cache. No symlink traversal or cross-filesystem recursion. Use full root only for an explicitly requested directory.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"maxEntries":{"type":"integer","minimum":1,"maximum":100000}},"additionalProperties":false}}}),
    ]
}

pub(super) fn operations() -> Vec<Value> {
    vec![
        json!({"type":"function","function":{"name":"files_pending","description":"List pending user confirmation proposals; this does not approve or execute them.","parameters":{"type":"object","properties":{},"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_delete","description":"Prepare file or recursive directory deletion. Returns an approval proposal; does NOT delete until the user confirms in the app. Do not claim deletion completed or bypass approval via shell.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"recursive":{"type":"boolean"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_prepare_overwrite","description":"Prepare an explicit overwrite approval for streaming upload. App user must approve; this tool alone does not grant permission.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"task_start","description":"Start large-file streaming transfer within controlled Downloads or service inbox. Use inbox for uploads when shared storage lacks atomic no-replace. Download hashes in background and becomes ready. Upload requires expected size and SHA-256. HTTP data path is returned; poll task_progress. Existing files are never overwritten.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"direction":{"type":"string","enum":["download","upload"]},"path":{"type":"string"},"sizeBytes":{"type":"integer","minimum":0},"sha256":{"type":"string"},"overwriteToken":{"type":"string"}},"required":["direction","path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"task_progress","description":"Read file transfer phase, byte progress, SHA-256 and final result.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"task_cancel","description":"Cancel an unfinished transfer and clean its temporary upload. Completed files remain.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_preview","description":"Open a short-lived read-only range stream for previewing a user-selected regular file within the selected root. Does not launch a target player or download the whole file. Release the returned id with files_preview_close.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_preview_close","description":"Release one file preview resource. Does not modify the source file or close a target player's media resource.","parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_download","description":"Snapshot a regular file within target Downloads or service inbox, up to 16 MiB. Returns a short-lived binary download path and SHA-256, never file contents as text. Use task_start for large-file streaming.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_url_info","description":"Read the suggested filename and optional size of an HTTP(S) URL from the target using response headers; does not save a file.","parameters":{"type":"object","properties":{"url":{"type":"string"}},"required":["url"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_download_url","description":"Download an HTTP(S) URL directly on the target. Optional root (default downloads), relative directory (default root), and name (default URL final segment or download.bin). Returns a url_download background task; poll task_progress and cancel with task_cancel. Never overwrites existing files.","parameters":{"type":"object","properties":{"url":{"type":"string"},"root":{"type":"string","enum":["downloads","inbox","full"]},"directory":{"type":"string"},"name":{"type":"string"}},"required":["url"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_mkdir","description":"Create one new directory inside the selected root. Parent must exist; relative paths only. Does not overwrite existing entries, follow symlinks, create parents or change permissions of existing paths.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"required":["path"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_list","description":"List a directory in Downloads, service inbox or explicitly selected full filesystem root. Relative paths only; symlinks cannot be followed. Cursor is the last filename of a previous page.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"},"cursor":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":100}},"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"files_stat","description":"Read metadata of a relative path inside the selected root.","parameters":{"type":"object","properties":{"root":{"type":"string","enum":["downloads","inbox","full"]},"path":{"type":"string"}},"additionalProperties":false}}}),
    ]
}
